270	function statusFor(session, lookup) {
271	  if (!session.sessionId) return { key: "missing", label: "Missing session" };
272	  if (lookup.state === "loading") return { key: "loading", label: "Checking" };
273	  if (lookup.state === "unconfigured") return { key: "unconfigured", label: "Not configured" };
274	  if (lookup.state === "error") return { key: "error", label: "Lookup error" };
275	  if (lookup.state === "ready") {
276	    if (lookup.evidence.matched) {
277	      const count = lookup.evidence.traces?.length || 0;
278	      return { key: "matched", label: `${count} trace${count === 1 ? "" : "s"}` };
279	    }
280	    return { key: "none", label: "No trace" };
281	  }
282	  return { key: "unchecked", label: "Unchecked" };
283	}
