294	  const [query, setQuery] = React.useState("");
295	  const [role, setRole] = React.useState("all");
296	  const [traceFilter, setTraceFilter] = React.useState("all");
297	  const [bulkChecking, setBulkChecking] = React.useState(false);
298	  const inFlight = React.useRef(new Map());
299	  const lookupSnapshot = React.useRef(lookups);
