316	    if (!session?.sessionId) return Promise.resolve(null);
317	    const active = inFlight.current.get(session.key);
318	    if (active) return active;
319	    // A refresh keeps the current trace on screen until the new one arrives.
320	    updateLookup(session.key, { ...lookupSnapshot.current[session.key], state: "loading" });
321	    const request = call("studio:evidence", { sessionId: session.sessionId })
