344	  const successful = Object.values(lookups).filter((item) => item.state === "ready");
345	  const matched = successful.filter((item) => item.evidence.matched).length;
346	  const linked = sessions.filter((session) => session.sessionId);
347	  const pending = linked.filter((session) => (lookups[session.key] || IDLE).state === "idle");
348	  const totalTokens = sessions.reduce((sum, session) => sum + (session.usage?.inputTokens || 0) + (session.usage?.outputTokens || 0), 0);
