350	  const roles = [...new Set(sessions.map((session) => session.role).filter(Boolean))];
351	  const filtered = sessions.filter((session) => {
352	    const status = statusFor(session, lookups[session.key] || IDLE).key;
353	    const haystack = [session.mod.name, ROLE[session.role] || session.role, session.model, session.sessionId, session.attemptN ? `attempt ${session.attemptN}` : "spec"].filter(Boolean).join(" ").toLowerCase();
