.studio .neatlogs-page {
  display: block;
  --nl-cyan: #78c5d6;
  --nl-cyan-soft: rgba(79, 184, 208, 0.12);
  --nl-workflow: #a78bfa;
  --nl-tool: #8b93ff;
  --nl-llm: #e8875a;
  --nl-sunk: #111215;
  --nl-tree-line: rgba(255, 255, 255, 0.11);
  padding: 30px 32px 42px;
}
.studio .neatlogs-page .nl-icon { fill: none; stroke: currentColor; stroke-width: 1.55; stroke-linecap: round; stroke-linejoin: round; }
.studio .neatlogs-page button, .studio .neatlogs-page input, .studio .neatlogs-page select { font: inherit; }
.studio .neatlogs-page .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.studio .neatlogs-page :is(button, input, select):focus-visible { outline: 2px solid var(--nl-cyan); outline-offset: 2px; }
.studio .neatlogs-page :is(.nl-header, .nl-heading, .nl-connection, .nl-browser-head, .nl-browser-head > div, .nl-toolbar) { display: flex; align-items: center; }
.studio .neatlogs-page .nl-header { justify-content: space-between; gap: 20px; margin-bottom: 18px; }
.studio .neatlogs-page .nl-heading { gap: 12px; }
.studio .neatlogs-page .nl-mark { display: grid; place-items: center; width: 36px; height: 36px; border: 1px solid var(--line-strong); border-radius: 9px; background: linear-gradient(145deg, #25272d, #141519); box-shadow: 0 1px 0 rgba(255,255,255,.08) inset, 0 6px 18px rgba(0,0,0,.18); color: #f4f4f5; font-size: 16px; font-weight: 650; }
.studio .neatlogs-page .nl-heading h1 { font-size: 22px; font-weight: 620; letter-spacing: -.025em; }
.studio .neatlogs-page .nl-heading p { margin-top: 3px; color: var(--text-3); font-size: 12.5px; }
.studio .neatlogs-page .nl-connection { gap: 8px; height: 28px; padding: 0 10px; border: 1px solid var(--line); border-radius: 999px; background: var(--panel); color: var(--text-2); font-size: 11.5px; white-space: nowrap; }
.studio .neatlogs-page :is(.nl-connection i, .nl-trace-status i, .nl-outcome i) { flex: none; width: 6px; height: 6px; border-radius: 50%; background: var(--text-3); }
.studio .neatlogs-page .nl-connection.connected i { background: var(--good); }
.studio .neatlogs-page .nl-connection.unreachable i { background: var(--bad); }
.studio .neatlogs-page .nl-connection.loading i { background: var(--warn); animation: nl-pulse 1.5s ease-in-out infinite; }
.studio .neatlogs-page .nl-connection-detail { margin: -7px 0 18px 48px; color: var(--text-3); font-size: 11.5px; }
.studio .neatlogs-page .nl-connection-detail.unreachable { color: var(--bad-text); }

.studio .neatlogs-page .nl-kpis { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); margin-bottom: 16px; border: 1px solid var(--line); border-radius: 11px; background: var(--panel); overflow: hidden; }
.studio .neatlogs-page .nl-kpis article { min-width: 0; padding: 17px 18px 16px; }
.studio .neatlogs-page .nl-kpis article + article { border-left: 1px solid var(--line); }
.studio .neatlogs-page .nl-kpis span { display: block; color: var(--text-2); font-size: 11.5px; }
