for (let tries = 0; ; tries++) {
  const vis = await entire(['repo', 'visibility', 'get', repo, '--json']);
  if (/"public"/i.test(vis.out)) return repo;
  const r = await entire(['repo', 'edit', repo, '--visibility', 'public', '--json']);
