input.content:
import React from "react";
import { call, ago } from "../../api.js";
import { fmtDuration } from "./shared.jsx";
import "./marketplace.css";

// Marketplace: mods published from the Studio. Each listing is a public Entire repo (source, sanitized checkpoints, and a
// meta branch with the spec, test plan and evidence); Supabase holds the rows (listings, versions, votes). Remixing clones a
// version or checkpoint from Entire with that context, so the remixer's agents can build on top of it.

function Icon({ name, size = 16 }) {
  const paths = {
    search: <><circle cx="7" cy="7" r="4.25" /><path d="m10.2 10.2 3.1 3.1" /></>,
    arrow: <path d="M4 8h8m-3.5-3.5L12 8l-3.5 3.5" />,
    back: <path d="M12 8H4m3.5-3.5L4 8l3.5 3.5" />,
    close: <path d="m4.5 4.5 7 7m0-7-7 7" />,
    retry: <><path d="M12.5 6A5 5 0 1 0 13 9" /><path d="M9.5 3.5h3v3" /></>,
    copy: <><rect x="5.5" y="5.5" width="7" height="7" rx="1.5" /><path d="M10.5 5.5V4a.5.5 0 0 0-.5-.5H4a.5.5 0 0 0-.5.5v6a.5.5 0 0 0 .5.5h1.5" /></>,
    check: <path d="M4 8.5 6.8 11 12 5.5" />,
    store: <><path d="M2.5 6.5 3.6 3h8.8l1.1 3.5" /><path d="M2.5 6.5a1.8 1.8 0 0 0 3.6 0 1.9 1.9 0 0 0 3.8 0 1.8 1.8 0 0 0 3.6 0" /><path d="M3.5 8.2V13h9V8.2M6.5 13v-2.8h3V13" /></>,
    remix: <><circle cx="4" cy="3.5" r="1.5" /><circle cx="4" cy="12.5" r="1.5" /><circle cx="12" cy="6" r="1.5" /><path d="M4 5v6M12 7.5c0 2.2-2 3-4 3.2-1.7.2-3 .7-3.6 1.4" /></>,
    checkpoint: <><path d="M1 8h4.2M10.8 8H15" /><path d="M8 5.2 10.8 8 8 10.8 5.2 8z" /></>,
    upload: <><path d="M8 11V3.5M5 6.5l3-3 3 3" /><path d="M3 10.5v2h10v-2" /></>,
    star: <path d="m8 2.6 1.6 3.4 3.7.4-2.8 2.5.8 3.7L8 10.7l-3.3 1.9.8-3.7-2.8-2.5 3.7-.4z" />,
    vote: <path d="M8 3.5 12.5 9h-3v3.5h-3V9h-3z" />,
    file: <><path d="M4.5 2.5h4.5l2.5 2.5v8.5h-7z" /><path d="M9 2.5V5h2.5" /></>,
    shield: <><path d="M8 2 13 4v3.8c0 3-2.2 5.2-5 6.2-2.8-1-5-3.2-5-6.2V4z" /><path d="m5.8 8 1.5 1.5 3-3" /></>,
    terminal: <><path d="M3.5 5 6 7.5 3.5 10" /><path d="M7.5 11h5" /></>,
    chevron: <path d="m5 6.5 3 3 3-3" />,
  };
  return <svg className="mk-icon" width={size} height={size} viewBox="0 0 16 16" aria-hidden="true">{paths[name]}</svg>;
}

const plural = (n, word) => `${Number(n || 0).toLocaleString()} ${word}${n === 1 ? "" : "s"}`;
const since = (date) => (date ? `${ago(new Date(date).getTime())} ago` : "");
const short = (s, n = 10) => (s ? s.slice(0, n) : "");
const clip = (t, n) => (!t || t.length <= n ? t || "" : `${t.slice(0, t.lastIndexOf(" ", n) > 0 ? t.lastIndexOf(" ", n) : n)}…`);
const latest = (l) => l.versions?.[0] || null;
const originOf = (l) => l.versions?.find((v) => v.entire?.origin)?.entire?.origin || null;
const repoOf = (l) => l.versions?.find((v) => v.entire?.remote?.repo)?.entire?.remote?.repo || null;
const PLAYTEST = { passed: "Playtest passed", failed: "Playtest failed", not_tested: "Not playtested", unknown: "Not playtested" };

function Copy({ text, label = "Copy" }) {
  const [done, setDone] = React.useState(false);
  return (
    <button className="mk-icon-button small" title={done ? "Copied" : label} aria-label={label}
      onClick={(e) => { e.stopPropagation(); navigator.clipboard?.writeText(text).then(() => { setDone(true); setTimeout(() => setDone(false), 1300); }); }}>
      <Icon name={done ? "check" : "copy"} size={13} />
    </button>
  );
}

function Pill({ kind, children }) {
  return <span className={`mk-pill ${kind || ""}`}><i />{children}</span>;
}

export default function MarketplacePage({ mods, onOpenMod = () => {} }) {
  const [state, setState] = React.useState(null);
  const [status, setStatus] = React.useState(null);
  const [error, setError] = React.useState("");
  const [selected, setSelected] = React.useState(null);
  const [query, setQuery] = React.useState("");
  const [filter, setFilter] = React.useState("all");
  const [publishing, setPublishing] = React.useState(false);

  const load = React.useCallback(() => {
    setError("");
    call("market:list").then(setState).catch((e) => setError(e.message));
    call("market:status").then(setStatus).catch(() => setStatus({ entire: { loggedIn: false, error: "Could not reach the Entire CLI." } }));
  }, []);
  React.useEffect(load, [load]);

  const listings = state?.listings || [];
  const remixesOf = React.useMemo(() => {
    const map = new Map();
    for (const l of listings) { const o = originOf(l); if (o?.slug) map.set(o.slug, [...(map.get(o.slug) || []), l]); }
    return map;
  }, [listings]);
  const listing = listings.find((l) => l.id === selected) || null;
  const filtered = listings.filter((l) => {
    const hay = `${l.name} ${l.slug} ${l.summary || ""}`.toLowerCase();
    const kind = filter === "all" || (filter === "originals" && !originOf(l)) || (filter === "remixes" && originOf(l)) || (filter === "entire" && repoOf(l)) || (filter === "passed" && latest(l)?.playtest_status === "passed");
    return kind && (!query.trim() || hay.includes(query.trim().toLowerCase()));
  });

  const versions = listings.reduce((n, l) => n + (l.versions?.length || 0), 0);
  const checkpoints = listings.reduce((n, l) => n + (latest(l)?.checkpoint_count || 0), 0);
  const transcripts = listings.reduce((n, l) => n + (latest(l)?.transcripts || 0), 0);
  const remixes = listings.filter(originOf).length;
  const onEntire = listings.filter(repoOf).length;

  const entire = status?.entire;
  const connection = !status ? "loading" : entire?.loggedIn ? "connected" : "off";
  const connectionLabel = { loading: "Checking Entire", connected: `Entire · ${entire?.handle || "signed in"}`, off: "Not signed in to Entire" }[connection];

  React.useEffect(() => {
    if (!listing) return undefined;
    const onKey = (e) => { if (e.key === "Escape" && !e.target.closest?.("input, textarea")) setSelected(null); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [listing]);

  return (
    <div className={`view market-page${listing ? " inspecting" : ""}`}>
      <header className="mk-header">
        <div className="mk-heading">
          <span className="mk-mark" aria-hidden="true"><Icon name="store" size={18} /></span>
          <div><h1>Marketplace</h1><p>Publish mods to Entire. Remix any version or checkpoint with its full build history.</p></div>
        </div>
        <div className="mk-header-actions">
          <span className={`mk-connection ${connection}`} title={entire?.error || (entire?.project ? `Listings are stored in the Entire project ${entire.project}` : "")}><i />{connectionLabel}</span>
          <button className="mk-icon-button" onClick={load} title="Refresh" aria-label="Refresh"><Icon name="retry" size={14} /></button>
          <button className="mk-primary" onClick={() => setPublishing(true)}><Icon name="upload" size={14} />Publish a mod</button>
        </div>
      </header>
      {connection === "off" && <div className="mk-notice">{entire?.error || "Sign in with `entire login` to publish and remix."} Publishing and remixing go through Entire.</div>}
      {error && <div className="mk-notice bad">{error}</div>}
      {state && !state.configured && <div className="mk-notice">The marketplace is not configured. Add the Supabase keys to .env.</div>}

      {listing ? (
        <div className="mk-focus">
          <aside className="mk-rail" aria-label="Listings">
            <button className="mk-back" onClick={() => setSelected(null)}><Icon name="back" size={14} />All listings</button>
            <div className="mk-rail-list">
              {listings.map((l) => (
                <button key={l.id} className={l.id === listing.id ? "active" : ""} aria-current={l.id === listing.id} onClick={() => setSelected(l.id)}>
                  <span>{l.name}{originOf(l) && <Icon name="remix" size={12} />}</span>
                  <small>v{latest(l)?.number || 0}</small>
                </button>
              ))}
            </div>
          </aside>
          <ListingView listing={listing} listings={listings} remixes={remixesOf.get(listing.slug) || []} onSelect={setSelected} onClose={() => setSelected(null)} onOpenMod={onOpenMod} canRemix={connection === "connected"} />
        </div>
      ) : (
        <>
          <section className="mk-kpis" aria-label="Marketplace summary">
            <article><span>Listings</span><strong>{listings.length}</strong><small>{listings.length - remixes} original · {remixes} remix{remixes === 1 ? "" : "es"}</small></article>
            <article><span>Versions</span><strong>{versions}</strong><small>{onEntire} listing{onEntire === 1 ? "" : "s"} stored on Entire</small></article>
            <article><span>Checkpoints shared</span><strong>{checkpoints}</strong><small>{transcripts} with sanitized transcripts</small></article>
            <article><span>Remixes</span><strong>{remixes}</strong><small>Built on top of another creator's mod</small></article>
          </section>

          <section className="mk-browser" aria-label="Listings">
            <div className="mk-browser-head"><div><h2>Listings</h2><span>{filtered.length} of {listings.length}</span></div></div>
            <div className="mk-toolbar">
              <label className="mk-search"><Icon name="search" size={15} /><span className="sr-only">Search listings</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search mods" /></label>
              <div className="mk-segments" aria-label="Filter listings">
                {[["all", "All"], ["originals", "Originals"], ["remixes", "Remixes"], ["entire", "On Entire"], ["passed", "Playtest passed"]].map(([value, label]) => (
                  <button key={value} className={filter === value ? "active" : ""} aria-pressed={filter === value} onClick={() => setFilter(value)}>{label}</button>
                ))}
              </div>
            </div>
            {!state ? <div className="mk-loading"><i /><span>Loading listings</span></div>
              : filtered.length ? (
                <div className="mk-grid">
                  {filtered.map((l) => <ListingCard key={l.id} listing={l} remixes={(remixesOf.get(l.slug) || []).length} onOpen={() => setSelected(l.id)} />)}
                </div>
              ) : (
                <div className="mk-empty"><Icon name="store" size={24} /><h3>{listings.length ? "No listings match" : "Nothing published yet"}</h3>
                  <p>{listings.length ? "Clear the search or filter to see every listing." : "Publish a finished mod. Its source, checkpoints and context go to a public Entire repo."}</p>
                  {listings.length ? <button onClick={() => { setQuery(""); setFilter("all"); }}>Clear filters</button> : <button onClick={() => setPublishing(true)}>Publish a mod</button>}
                </div>
              )}
          </section>
        </>
      )}

      {publishing && <PublishSheet mods={mods} listings={listings} entire={entire} onClose={() => setPublishing(false)} onPublished={load} />}
    </div>
  );
}

function ListingCard({ listing, remixes, onOpen }) {
  const v = latest(listing);
  const origin = originOf(listing);
  const repo = repoOf(listing);
  return (
    <button className="mk-card" onClick={onOpen}>
      <div className="mk-card-top">
        <span className="mk-avatar" aria-hidden="true">{listing.name.slice(0, 1)}</span>
        <div className="mk-card-title"><strong>{listing.name}</strong><span>v{v?.number || 0} · {since(v?.created_at || listing.created_at)}</span></div>
        <Pill kind={v?.playtest_status}>{PLAYTEST[v?.playtest_status] || "Not playtested"}</Pill>
      </div>
      {origin && <span className="mk-lineage-chip"><Icon name="remix" size={12} />Remix of {origin.name || origin.slug} v{origin.version}</span>}
      <p>{clip(listing.summary, 150) || "No description."}</p>
      <div className="mk-card-foot">
        <span title="Checkpoints"><Icon name="checkpoint" size={13} />{v?.checkpoint_count || 0}</span>
        <span title="Votes"><Icon name="vote" size={13} />{listing.stats?.votes || 0}</span>
        {listing.stats?.stars && <span title="Rating"><Icon name="star" size={13} />{Number(listing.stats.stars).toFixed(1)}</span>}
        <span title="Remixes"><Icon name="remix" size={13} />{remixes}</span>
        <span className={`mk-where ${repo ? "entire" : ""}`}>{repo ? "Entire" : "Local only"}</span>
      </div>
    </button>
  );
}

function ListingView({ listing, listings, remixes, onSelect, onClose, onOpenMod, canRemix }) {
  const [tab, setTab] = React.useState("checkpoints");
  const [vn, setVn] = React.useState(latest(listing)?.number);
  const [busy, setBusy] = React.useState(null);
  const [error, setError] = React.useState("");
  React.useEffect(() => { setVn(latest(listing)?.number); setError(""); }, [listing.id]);
  const version = listing.versions?.find((v) => v.number === vn) || latest(listing);
  const ent = version?.entire || {};
  const repo = ent.remote?.repo || null;
  const origin = originOf(listing);
  const parent = origin ? listings.find((l) => l.slug === origin.slug) : null;

  const remix = (checkpointId = null) => {
    setBusy(checkpointId || "version");
    setError("");
    call("market:open-checkpoint", { slug: listing.slug, number: version.number, checkpointId })
      .then((mod) => onOpenMod(mod.id))
      .catch((e) => setError(e.message))
      .finally(() => setBusy(null));
  };
  const remixBlocked = !canRemix && repo ? "Sign in to Entire to remix" : null;

  const stats = [
    ["Version", `v${version?.number}`, since(version?.created_at)],
    ["Checkpoints", version?.checkpoint_count ?? 0, `${version?.transcripts || 0} with transcripts`],
    ["Tokens", Number(version?.tokens || 0).toLocaleString(), "Spent building it"],
    ["Playtest", PLAYTEST[version?.playtest_status] || "—", version?.playtest_status === "passed" ? "Every check passed" : "Self-reported by the Studio"],
  ];
  const tabs = [
    ["checkpoints", `Checkpoints`, ent.checkpoints?.length || 0],
    ["context", "Context", null],
    ["changelog", "Changelog", ent.changelog?.filesChanged ?? null],
    ["versions", "Versions", listing.versions?.length || 0],
    ["remixes", "Remixes", remixes.length],
  ];

  return (
    <section className="mk-detail" aria-label={listing.name}>
      <header className="mk-detail-head">
        <div className="mk-detail-title">
          <span className="mk-crumbs">Marketplace<i>/</i>{listing.slug}</span>
          <h2>{listing.name}<Pill kind={version?.playtest_status}>{PLAYTEST[version?.playtest_status] || "Not playtested"}</Pill></h2>
          <p>{listing.summary}</p>
        </div>
        <div className="mk-detail-actions">
          <button className="mk-primary" disabled={Boolean(busy) || Boolean(remixBlocked)} title={remixBlocked || "Clone this version from Entire and open it in the Studio"} onClick={() => remix(null)}>
            <Icon name="remix" size={14} />{busy === "version" ? "Cloning from Entire…" : `Remix v${version?.number}`}
          </button>
          <button className="mk-icon-button" onClick={onClose} title="Close (Esc)" aria-label="Close listing"><Icon name="close" size={14} /></button>
        </div>
      </header>
      {error && <div className="mk-notice bad inset">{error}</div>}

      {origin && (
        <div className="mk-lineage">
          <Icon name="remix" size={15} />
          <span>Remixed from <button className="mk-link" disabled={!parent} onClick={() => parent && onSelect(parent.id)}>{origin.name || origin.slug} v{origin.version}</button>
            {origin.checkpoint ? <> at checkpoint <code>{short(origin.checkpoint, 12)}</code></> : null}{origin.commit ? <> · commit <code>{short(origin.commit, 7)}</code></> : null}</span>
        </div>
      )}

      <dl className="mk-stats">
        {stats.map(([label, value, sub]) => <div key={label}><dt>{label}</dt><dd>{value}</dd><small>{sub}</small></div>)}
        <div className="mk-stat-repo"><dt>Stored on</dt><dd>{repo ? <><code>{repo}</code><Copy text={repo} label="Copy repo path" /></> : <span className="mk-muted">This machine only</span>}</dd><small>{repo ? "Public Entire repo" : "Republish to store it on Entire"}</small></div>
      </dl>

      <div className="mk-tabs" role="tablist">
        {tabs.map(([id, label, count]) => (
          <button key={id} role="tab" aria-selected={tab === id} className={tab === id ? "active" : ""} onClick={() => setTab(id)}>{label}{count != null && <small>{count}</small>}</button>
        ))}
        {listing.versions?.length > 1 && (
          <label className="mk-version-pick"><span className="sr-only">Version</span>
            <select value={version?.number} onChange={(e) => setVn(Number(e.target.value))}>{listing.versions.map((v) => <option key={v.id} value={v.number}>v{v.number}</option>)}</select>
            <Icon name="chevron" size={12} />
          </label>
        )}
      </div>

      <div className="mk-tab-body">
        {tab === "checkpoints" && <Checkpoints entire={ent} version={version} busy={busy} onRemix={remix} remixBlocked={remixBlocked} />}
        {tab === "context" && <Context listing={listing} version={version} repo={repo} />}
        {tab === "changelog" && <Changelog entire={ent} />}
        {tab === "versions" && <Versions listing={listing} current={version?.number} onPick={(n) => { setVn(n); setTab("checkpoints"); }} />}
        {tab === "remixes" && (remixes.length ? (
          <ul className="mk-remix-list">{remixes.map((r) => { const o = originOf(r); return (
            <li key={r.id}><button onClick={() => onSelect(r.id)}><Icon name="remix" size={14} /><span><strong>{r.name}</strong><small>{r.slug} · from v{o?.version}{o?.checkpoint ? ` @ ${short(o.checkpoint, 10)}` : ""}</small></span><Pill kind={latest(r)?.playtest_status}>{PLAYTEST[latest(r)?.playtest_status] || "Not playtested"}</Pill><Icon name="arrow" size={14} /></button></li>
          ); })}</ul>
        ) : <div className="mk-empty small"><Icon name="remix" size={22} /><h3>No remixes yet</h3><p>Remix a version or a checkpoint, change it in the Studio, then publish. It shows up here with its lineage.</p></div>)}
      </div>
    </section>
  );
}

function Checkpoints({ entire, version, busy, onRemix, remixBlocked }) {
  const cps = entire.checkpoints || [];
  const [selected, setSelected] = React.useState(cps.at(-1)?.id || null);
  React.useEffect(() => setSelected(cps.at(-1)?.id || null), [version?.id]);
  const cp = cps.find((c) => c.id === selected) || cps.at(-1) || null;
  const pushed = new Set((entire.remote?.checkpoints || []).map((c) => c.id));
  if (!cps.length) return <div className="mk-empty small"><Icon name="checkpoint" size={22} /><h3>No checkpoints in this version</h3><p>You can still remix the version itself.</p></div>;
  return (
    <div className="mk-explorer">
      <ol className="mk-timeline" aria-label="Checkpoints, oldest first">
        {cps.map((c, i) => (
          <li key={c.id}>
            <button className={c.id === cp?.id ? "active" : ""} aria-current={c.id === cp?.id} onClick={() => setSelected(c.id)}>
              <span className="mk-node" aria-hidden="true" />
              <span className="mk-tl-main">
                <strong>{c.summary?.intent ? clip(c.summary.intent, 70) : `Checkpoint ${i + 1}`}</strong>
                <small><code>{short(c.id, 10)}</code>{c.agent ? ` · ${c.agent}` : ""}{c.createdAt ? ` · ${since(c.createdAt)}` : ""}</small>
              </span>
              {c.hasTranscript && <span className="mk-tag">transcript</span>}
            </button>
          </li>
        ))}
      </ol>
      {cp && (
        <div className="mk-cp-panel">
          <span className="mk-eyebrow">Checkpoint</span>
          <h3><code>{cp.id}</code><Copy text={cp.id} label="Copy checkpoint ID" /></h3>
          {cp.summary && (
            <div className="mk-summary">
              <p><b>Intent</b>{cp.summary.intent}</p>
              <p><b>Outcome</b>{cp.summary.outcome}</p>
              {cp.summary.learnings && <p className="mk-muted">{cp.summary.learnings}</p>}
            </div>
          )}
          <dl className="mk-facts">
            <dt>Commit</dt><dd><code>{cp.commit ? short(cp.commit, 10) : "not linked"}</code></dd>
            <dt>Agent</dt><dd>{cp.agent || "—"}{cp.model ? <span className="mk-muted"> · {cp.model}</span> : null}</dd>
            <dt>Sessions</dt><dd>{cp.sessions} · {cp.hasTranscript ? "sanitized transcript" : "metadata only"}</dd>
            <dt>Tokens</dt><dd>{Number(cp.tokens || 0).toLocaleString()}</dd>
            <dt>On Entire</dt><dd>{pushed.has(cp.id) ? "Native checkpoint ref, explainable in a clone" : "Not pushed"}</dd>
          </dl>
          {cp.files?.length > 0 && <div className="mk-files">{cp.files.map((f) => <code key={f}>{f}</code>)}</div>}
          <div className="mk-remix-box">
            <button className="mk-primary" disabled={Boolean(busy) || !cp.commit || Boolean(remixBlocked)} title={remixBlocked || ""} onClick={() => onRemix(cp.id)}>
              <Icon name="remix" size={14} />{busy === cp.id ? "Cloning from Entire…" : "Remix from here"}
            </button>
            <p>Clones the mod at commit <code>{short(cp.commit, 7)}</code> with the parent's checkpoints, spec and test plan, writes a REMIX.md brief for your agents, and opens it in the Studio. Nothing is published until you publish.</p>
          </div>
        </div>
      )}
    </div>
  );
}

function Context({ listing, version, repo }) {
  const clone = repo ? `entire repo clone ${repo}\ncd ${listing.slug}\ngit fetch origin '+refs/entire/checkpoints/*:refs/entire/checkpoints/*' '+refs/heads/benana/meta:refs/remotes/origin/benana/meta'\ngit checkout marketplace/v${version?.number}` : null;
  return (
    <div className="mk-context">
      <section>
        <span className="mk-eyebrow">What a remix starts with</span>
        <ul className="mk-included">
          <li><Icon name="file" size={14} /><span><b>Source</b> at the version or checkpoint commit, with its full git history</span></li>
          <li><Icon name="checkpoint" size={14} /><span><b>Entire checkpoints</b> for this version, sanitized: <code>entire checkpoint explain</code> works in the clone</span></li>
          <li><Icon name="terminal" size={14} /><span><b>context.json</b>: the spec, behavior list, in-game test plan, build requests and fixer lessons</span></li>
          <li><Icon name="shield" size={14} /><span><b>Gated</b>: home paths, usernames and emails replaced; gitleaks and an entropy check block any secret</span></li>
        </ul>
      </section>
      <section>
        <span className="mk-eyebrow">Playtest</span>
        <p className="mk-prose">{version?.playtest_summary || "No playtest summary."}</p>
      </section>
      {clone && (
        <section>
          <span className="mk-eyebrow">Clone it yourself</span>
          <div className="mk-code"><pre>{clone}</pre><Copy text={clone} label="Copy commands" /></div>
        </section>
      )}
      <section>
        <span className="mk-eyebrow">Integrity</span>
        <dl className="mk-facts">
          <dt>Jar SHA-256</dt><dd><code>{version?.jar_sha256}</code></dd>
          <dt>Manifest</dt><dd><code>{version?.bundle_manifest_sha256}</code></dd>
          <dt>Commit</dt><dd><code>{version?.commit_sha}</code></dd>
          {version?.entire?.codeMap && <><dt>Code map</dt><dd>{version.entire.codeMap.symbols} symbols · {version.entire.codeMap.relations} relations</dd></>}
        </dl>
      </section>
    </div>
  );
}

function Changelog({ entire }) {
  const cl = entire.changelog;
  if (!cl?.files?.length) return <div className="mk-empty small"><Icon name="file" size={22} /><h3>No changelog for this version</h3><p>The graph diff did not run when it was published.</p></div>;
  return (
    <ul className="mk-changes">
      {cl.files.map((f) => (
        <li key={f.path}>
          <span className={`mk-status ${f.status}`}>{f.status === "A" ? "added" : f.status === "D" ? "deleted" : "changed"}</span>
          <code>{f.path}</code>
          <span className="mk-change-counts">{f.added > 0 && <b className="add">+{f.added}</b>}{f.removed > 0 && <b className="del">−{f.removed}</b>}{f.signatureChanged > 0 && <b>{plural(f.signatureChanged, "signature change")}</b>}</span>
          {f.names?.length > 0 && <small>{f.names.join(", ")}</small>}
        </li>
      ))}
    </ul>
  );
}

function Versions({ listing, current, onPick }) {
  return (
    <table className="mk-table">
      <thead><tr><th>Version</th><th>Commit</th><th>Playtest</th><th className="num">Checkpoints</th><th>Stored on</th><th>Published</th></tr></thead>
      <tbody>
        {(listing.versions || []).map((v) => (
          <tr key={v.id} className={v.number === current ? "current" : ""} onClick={() => onPick(v.number)}>
            <td><strong>v{v.number}</strong></td>
            <td><code>{short(v.commit_sha, 7)}</code></td>
            <td><Pill kind={v.playtest_status}>{PLAYTEST[v.playtest_status] || "—"}</Pill></td>
            <td className="num">{v.checkpoint_count}</td>
            <td>{v.entire?.remote ? <span className="mk-where entire">Entire</span> : <span className="mk-where">Local only</span>}</td>
            <td className="mk-muted">{since(v.created_at)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function PublishSheet({ mods, listings, entire, onClose, onPublished }) {
  const publishable = mods.filter((m) => m.repoDir && ["passed", "failed"].includes(m.status));
  React.useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
  return (
    <div className="mk-sheet-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <aside className="mk-sheet" role="dialog" aria-label="Publish a mod">
        <header>
          <div><h2>Publish a mod</h2><p>Each version goes to a public Entire repo in <code>{entire?.project || "benana-market"}</code>.</p></div>
          <button className="mk-icon-button" onClick={onClose} aria-label="Close"><Icon name="close" size={14} /></button>
        </header>
        <ol className="mk-steps">
          <li><b>1</b>Gate: sanitize identity, scan for secrets, build the evidence bundle</li>
          <li><b>2</b>Push source, sanitized checkpoints and context to Entire</li>
          <li><b>3</b>List it here. Remixes credit the mod they came from</li>
        </ol>
        {!entire?.loggedIn && <div className="mk-notice">Not signed in to Entire. Run <code>entire login</code>, then refresh.</div>}
        <div className="mk-sheet-list">
          {!publishable.length && <p className="mk-muted">Finish a mod's build and playtest first. Only passed or failed mods can be published.</p>}
          {publishable.map((m) => <PublishCard key={m.id} mod={m} published={listings.find((l) => l.slug === m.marketSlug)} disabled={!entire?.loggedIn} onPublished={onPublished} />)}
        </div>
      </aside>
    </div>
  );
}

function PublishCard({ mod, published, disabled, onPublished }) {
  const [busy, setBusy] = React.useState(false);
  const [result, setResult] = React.useState(null);
  const [summaries, setSummaries] = React.useState(false);
  const [started, setStarted] = React.useState(0);
  const [, tick] = React.useState(0);
  React.useEffect(() => { if (!busy) return undefined; const t = setInterval(() => tick((n) => n + 1), 1000); return () => clearInterval(t); }, [busy]);
  const run = (metadataOnly) => {
    setBusy(true);
    setStarted(Date.now());
    setResult(null);
    call("market:publish", { id: mod.id, metadataOnly, withSummaries: summaries })
      .then((r) => { setResult(r); onPublished(); })
      .catch((e) => setResult({ ok: false, error: e.message }))
      .finally(() => setBusy(false));
  };
  const blocked = result && result.ok === false && result.blocked;
  const findings = blocked ? [...(result.gate?.findings || []), ...(result.gate?.suspicious || [])] : [];
  const last = published?.versions?.[0];
  return (
    <div className="mk-pub">
      <div className="mk-pub-head">
        <span className="mk-avatar small" aria-hidden="true">{mod.name.slice(0, 1)}</span>
        <div><strong>{mod.name}</strong><small>{mod.origin ? `Remix of ${mod.origin.name || mod.origin.marketplace} v${mod.origin.version}` : mod.marketSlug}</small></div>
        <Pill kind={mod.status === "passed" ? "passed" : "failed"}>{mod.status === "passed" ? "Passed" : "Failed"}</Pill>
      </div>
      <p className="mk-muted">{clip(mod.spec?.summary || mod.prompt, 140)}</p>
      {last && <p className="mk-pub-state">Listed as v{last.number}{last.entire?.remote ? " on Entire" : " (local only)"} · {since(last.created_at)}</p>}
      <label className="mk-opt"><input type="checkbox" checked={summaries} onChange={(e) => setSummaries(e.target.checked)} />Write AI checkpoint summaries <span className="mk-muted">(uses your summarizer credits)</span></label>
      <button className="mk-primary block" disabled={busy || disabled} onClick={() => run(false)}>
        <Icon name="upload" size={14} />{busy ? `Publishing… ${fmtDuration(Date.now() - started) || ""}` : published ? "Publish a new version" : "Publish with transcripts"}
      </button>
      {result?.ok && !result.skipped && <p className="mk-ok">Published v{result.version.number}{result.version.entire?.remote ? ` to ${result.version.entire.remote.repo}` : ""}.</p>}
      {result?.ok && result.skipped && <p className="mk-muted">{result.skipped}</p>}
      {result && !result.ok && !blocked && <p className="mk-err">{result.error}</p>}
      {blocked && (
        <div className="mk-blocked" role="alert">
          <p>Blocked by the secret gate: {plural(findings.length, "item")} to review before this can be published.</p>
          <ul>{findings.slice(0, 6).map((f, i) => <li key={i}><code>{f.file || "transcript"}</code> line {f.line} · {f.rule || "random-looking token"}</li>)}</ul>
          {result.metadataOnlyPossible && <button className="mk-button" disabled={busy} onClick={() => run(true)}>Publish metadata only</button>}
        </div>
      )}
    </div>
  );
}

