input.content:
import React from "react";
import { call, ago } from "../../api.js";
import { fmtDuration } from "./shared.jsx";
import "./marketplace.css";

// Marketplace: mods published from the Studio. Each listing is a public Entire repo (source, sanitized checkpoints, and a
// meta branch with the spec, test plan and evidence); Supabase holds the rows (listings, versions, votes). Remixing clones a
// version or checkpoint from Entire with that context, so the remixer's agents can build on top of it.

function Icon({ name, size = 16 }) {
  const paths = {
    search: <><circle cx="7" cy="7" r="4.25" /><path d="m10.2 10.2 3.1 3.1" /></>,
    back: <path d="M12 8H4m3.5-3.5L4 8l3.5 3.5" />,
    close: <path d="m4.5 4.5 7 7m0-7-7 7" />,
    copy: <><rect x="5.5" y="5.5" width="7" height="7" rx="1.5" /><path d="M10.5 5.5V4a.5.5 0 0 0-.5-.5H4a.5.5 0 0 0-.5.5v6a.5.5 0 0 0 .5.5h1.5" /></>,
    check: <path d="M4 8.5 6.8 11 12 5.5" />,
    remix: <><circle cx="4" cy="3.5" r="1.5" /><circle cx="4" cy="12.5" r="1.5" /><circle cx="12" cy="6" r="1.5" /><path d="M4 5v6M12 7.5c0 2.2-2 3-4 3.2-1.7.2-3 .7-3.6 1.4" /></>,
    entire: <><path d="M1 8h4.2M10.8 8H15" /><path d="M8 5.2 10.8 8 8 10.8 5.2 8z" /></>,
    upload: <><path d="M8 11V3.5M5 6.5l3-3 3 3" /><path d="M3 10.5v2h10v-2" /></>,
    file: <><path d="M4.5 2.5h4.5l2.5 2.5v8.5h-7z" /><path d="M9 2.5V5h2.5" /></>,
    chevron: <path d="m5 6.5 3 3 3-3" />,
  };
  return <svg className="mk-icon" width={size} height={size} viewBox="0 0 16 16" aria-hidden="true">{paths[name]}</svg>;
}

const since = (date) => (date ? `${ago(new Date(date).getTime())} ago` : "");
const short = (s, n = 10) => (s ? s.slice(0, n) : "");
const latest = (l) => l.versions?.[0] || null;
const originOf = (l) => l.versions?.find((v) => v.entire?.origin)?.entire?.origin || null;
const repoOf = (l) => l.versions?.find((v) => v.entire?.remote?.repo)?.entire?.remote?.repo || null;

function Copy({ text, label = "Copy" }) {
  const [done, setDone] = React.useState(false);
  return (
    <button className="mk-icon-button small" title={done ? "Copied" : label} aria-label={label}
      onClick={(e) => { e.stopPropagation(); navigator.clipboard?.writeText(text).then(() => { setDone(true); setTimeout(() => setDone(false), 1300); }); }}>
      <Icon name={done ? "check" : "copy"} size={13} />
    </button>
  );
}

// The Entire badge: shown wherever something lives on, or comes from, Entire.
function EntireBadge({ children = "Entire" }) {
  return <span className="mk-entire"><Icon name="entire" size={12} />{children}</span>;
}

const Passed = ({ status }) => (status === "passed" ? <span className="mk-passed" title="Playtest passed"><Icon name="check" size={12} />Tested</span> : null);

export default function MarketplacePage({ mods, onOpenMod = () => {} }) {
  const [state, setState] = React.useState(null);
  const [status, setStatus] = React.useState(null);
  const [error, setError] = React.useState("");
  const [selected, setSelected] = React.useState(null);
  const [query, setQuery] = React.useState("");
  const [filter, setFilter] = React.useState("all");
  const [publishing, setPublishing] = React.useState(false);

  const load = React.useCallback(() => {
    setError("");
    call("market:list").then(setState).catch((e) => setError(e.message));
    call("market:status").then(setStatus).catch(() => setStatus({ entire: { loggedIn: false } }));
  }, []);
  React.useEffect(load, [load]);

  const listings = state?.listings || [];
  const remixesOf = React.useMemo(() => {
    const map = new Map();
    for (const l of listings) { const o = originOf(l); if (o?.slug) map.set(o.slug, [...(map.get(o.slug) || []), l]); }
    return map;
  }, [listings]);
  const listing = listings.find((l) => l.id === selected) || null;
  const filtered = listings.filter((l) => {
    const kind = filter === "all" || (filter === "remixes" && originOf(l)) || (filter === "tested" && latest(l)?.playtest_status === "passed");
    return kind && (!query.trim() || `${l.name} ${l.summary || ""}`.toLowerCase().includes(query.trim().toLowerCase()));
  });

  const entire = status?.entire;
  const signedIn = Boolean(entire?.loggedIn);

  React.useEffect(() => {
    if (!listing) return undefined;
    const onKey = (e) => { if (e.key === "Escape" && !e.target.closest?.("input, textarea")) setSelected(null); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [listing]);

  return (
    <div className={`view market-page${listing ? " inspecting" : ""}`}>
      <header className="mk-header">
        <div className="mk-heading">
          <h1>Marketplace</h1>
          <span className={`mk-powered ${status ? (signedIn ? "on" : "off") : ""}`} title={signedIn ? `Signed in as ${entire.handle}` : "Run `entire login` to publish and remix"}>
            <Icon name="entire" size={13} />Powered by Entire{status && !signedIn && <b>· sign in</b>}
          </span>
        </div>
        <button className="mk-primary" onClick={() => setPublishing(true)}><Icon name="upload" size={14} />Publish</button>
      </header>
      {error && <div className="mk-notice">{error}</div>}

      {listing ? (
        <div className="mk-focus">
          <aside className="mk-rail" aria-label="Listings">
            <button className="mk-back" onClick={() => setSelected(null)}><Icon name="back" size={14} />All mods</button>
            {listings.map((l) => (
              <button key={l.id} className={l.id === listing.id ? "active" : ""} aria-current={l.id === listing.id} onClick={() => setSelected(l.id)}>
                <span>{l.name}</span>{originOf(l) && <Icon name="remix" size={12} />}
              </button>
            ))}
          </aside>
          <ListingView listing={listing} listings={listings} remixes={remixesOf.get(listing.slug) || []} onSelect={setSelected} onClose={() => setSelected(null)} onOpenMod={onOpenMod} signedIn={signedIn} />
        </div>
      ) : (
        <>
          <div className="mk-toolbar">
            <label className="mk-search"><Icon name="search" size={15} /><span className="sr-only">Search mods</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search mods" /></label>
            <div className="mk-segments" aria-label="Filter">
              {[["all", "All"], ["tested", "Tested"], ["remixes", "Remixes"]].map(([value, label]) => (
                <button key={value} className={filter === value ? "active" : ""} aria-pressed={filter === value} onClick={() => setFilter(value)}>{label}</button>
              ))}
            </div>
          </div>
          {!state ? <div className="mk-loading"><i /></div>
            : filtered.length ? (
              <div className="mk-grid">
                {filtered.map((l) => <ListingCard key={l.id} listing={l} remixes={(remixesOf.get(l.slug) || []).length} onOpen={() => setSelected(l.id)} />)}
              </div>
            ) : (
              <div className="mk-empty">
                <h3>{listings.length ? "No mods match" : "Nothing published yet"}</h3>
                {listings.length ? <button onClick={() => { setQuery(""); setFilter("all"); }}>Clear filters</button> : <button onClick={() => setPublishing(true)}>Publish a mod</button>}
              </div>
            )}
        </>
      )}

      {publishing && <PublishSheet mods={mods} listings={listings} signedIn={signedIn} onClose={() => setPublishing(false)} onPublished={load} />}
    </div>
  );
}

function ListingCard({ listing, remixes, onOpen }) {
  const v = latest(listing);
  const origin = originOf(listing);
  return (
    <button className="mk-card" onClick={onOpen}>
      <div className="mk-card-top">
        <span className="mk-avatar" aria-hidden="true">{listing.name.slice(0, 1)}</span>
        <strong>{listing.name}</strong>
        <Passed status={v?.playtest_status} />
      </div>
      <p>{origin ? <span className="mk-from">Remix of {origin.name || origin.slug} · </span> : null}{listing.summary || "No description."}</p>
      <div className="mk-card-foot">
        {repoOf(listing) ? <EntireBadge>{v?.checkpoint_count || 0} checkpoints</EntireBadge> : <span className="mk-local">Not on Entire yet</span>}
        {remixes > 0 && <span><Icon name="remix" size={12} />{remixes}</span>}
        <span className="mk-ver">v{v?.number || 0}</span>
      </div>
    </button>
  );
}

function ListingView({ listing, listings, remixes, onSelect, onClose, onOpenMod, signedIn }) {
  const [tab, setTab] = React.useState("checkpoints");
  const [vn, setVn] = React.useState(latest(listing)?.number);
  const [busy, setBusy] = React.useState(null);
  const [error, setError] = React.useState("");
  React.useEffect(() => { setVn(latest(listing)?.number); setError(""); setTab("checkpoints"); }, [listing.id]);
  const version = listing.versions?.find((v) => v.number === vn) || latest(listing);
  const ent = version?.entire || {};
  const repo = ent.remote?.repo || null;
  const origin = originOf(listing);
  const parent = origin ? listings.find((l) => l.slug === origin.slug) : null;
  const blocked = !repo ? "Not on Entire yet. The creator needs to publish it again." : !signedIn ? "Sign in to Entire to remix" : null;

  const remix = (checkpointId = null) => {
    setBusy(checkpointId || "version");
    setError("");
    call("market:open-checkpoint", { slug: listing.slug, number: version.number, checkpointId })
      .then((mod) => onOpenMod(mod.id))
      .catch((e) => setError(e.message))
      .finally(() => setBusy(null));
  };
  const clone = repo ? `entire repo clone ${repo}` : "";

  return (
    <section className="mk-detail" aria-label={listing.name}>
      <header className="mk-detail-head">
        <div className="mk-detail-title">
          <h2>{listing.name}<Passed status={version?.playtest_status} /></h2>
          <p>{listing.summary}</p>
          {origin && (
            <p className="mk-lineage"><Icon name="remix" size={13} />Remix of <button className="mk-link" disabled={!parent} onClick={() => parent && onSelect(parent.id)}>{origin.name || origin.slug} v{origin.version}</button></p>
          )}
        </div>
        <div className="mk-detail-actions">
          <button className="mk-primary" disabled={Boolean(busy) || Boolean(blocked)} title={blocked || ""} onClick={() => remix(null)}>
            <Icon name="remix" size={14} />{busy === "version" ? "Cloning…" : "Remix"}
          </button>
          <button className="mk-icon-button" onClick={onClose} title="Close (Esc)" aria-label="Close"><Icon name="close" size={14} /></button>
        </div>
      </header>

      <div className="mk-repo">
        {repo ? <>
          <EntireBadge />
          <code>{repo}</code>
          <Copy text={clone} label="Copy clone command" />
        </> : <span className="mk-local">Not on Entire yet</span>}
        {listing.versions?.length > 1 ? (
          <label className="mk-version-pick"><span className="sr-only">Version</span>
            <select value={version?.number} onChange={(e) => setVn(Number(e.target.value))}>{listing.versions.map((v) => <option key={v.id} value={v.number}>v{v.number}</option>)}</select>
            <Icon name="chevron" size={12} />
          </label>
        ) : <span className="mk-ver">v{version?.number}</span>}
      </div>
      {error && <div className="mk-notice inset">{error}</div>}

      <div className="mk-tabs" role="tablist">
        {[["checkpoints", "Checkpoints", ent.checkpoints?.length || 0], ["remixes", "Remixes", remixes.length]].map(([id, label, count]) => (
          <button key={id} role="tab" aria-selected={tab === id} className={tab === id ? "active" : ""} onClick={() => setTab(id)}>{label}<small>{count}</small></button>
        ))}
      </div>

      <div className="mk-tab-body">
        {tab === "checkpoints" && <Checkpoints entire={ent} version={version} busy={busy} onRemix={remix} blocked={blocked} />}
        {tab === "remixes" && (remixes.length ? (
          <ul className="mk-remix-list">{remixes.map((r) => (
            <li key={r.id}><button onClick={() => onSelect(r.id)}><Icon name="remix" size={14} /><strong>{r.name}</strong><span className="mk-ver">v{latest(r)?.number}</span></button></li>
          ))}</ul>
        ) : <div className="mk-empty small"><h3>No remixes yet</h3></div>)}
      </div>
    </section>
  );
}

// What a checkpoint did, for its timeline label: its AI summary if published, else the files it touched.
function cpTitle(c, i) {
  if (c.summary?.intent) return c.summary.intent;
  const names = (c.files || []).map((f) => f.split("/").pop());
  return names.length ? `${names.slice(0, 2).join(", ")}${names.length > 2 ? ` +${names.length - 2}` : ""}` : `Checkpoint ${i + 1}`;
}

function Checkpoints({ entire, version, busy, onRemix, blocked }) {
  const cps = React.useMemo(() => [...(entire.checkpoints || [])].sort((a, b) => String(a.createdAt || "").localeCompare(String(b.createdAt || ""))), [entire.checkpoints]);
  const [selected, setSelected] = React.useState(cps.at(-1)?.id || null);
  React.useEffect(() => setSelected(cps.at(-1)?.id || null), [version?.id]);
  const cp = cps.find((c) => c.id === selected) || cps.at(-1) || null;
  if (!cps.length) return <div className="mk-empty small"><h3>No checkpoints in this version</h3></div>;
  return (
    <div className="mk-explorer">
      <ol className="mk-timeline" aria-label="Checkpoints, oldest first">
        {cps.map((c, i) => (
          <li key={c.id}>
            <button className={c.id === cp?.id ? "active" : ""} aria-current={c.id === cp?.id} onClick={() => setSelected(c.id)}>
              <span className="mk-node" aria-hidden="true" />
              <span className="mk-tl-main"><strong>{cpTitle(c, i)}</strong><small>{c.agent || "Agent"}{c.createdAt ? ` · ${since(c.createdAt)}` : ""}</small></span>
            </button>
          </li>
        ))}
      </ol>
      {cp && (
        <div className="mk-cp-panel">
          <div className="mk-cp-id"><EntireBadge>Checkpoint</EntireBadge><code>{short(cp.id, 12)}</code><Copy text={cp.id} label="Copy checkpoint ID" /></div>
          {cp.summary?.outcome && <p className="mk-cp-summary">{cp.summary.outcome}</p>}
          {cp.files?.length > 0 && <div className="mk-files">{cp.files.slice(0, 6).map((f) => <code key={f}><Icon name="file" size={11} />{f.split("/").pop()}</code>)}</div>}
          <button className="mk-primary" disabled={Boolean(busy) || !cp.commit || Boolean(blocked)} title={blocked || "Clone the mod at this checkpoint, with its history"} onClick={() => onRemix(cp.id)}>
            <Icon name="remix" size={14} />{busy === cp.id ? "Cloning from Entire…" : "Remix from here"}
          </button>
        </div>
      )}
    </div>
  );
}

function PublishSheet({ mods, listings, signedIn, onClose, onPublished }) {
  const publishable = mods.filter((m) => m.repoDir && ["passed", "failed"].includes(m.status));
  const [summaries, setSummaries] = React.useState(false);
  React.useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
  return (
    <div className="mk-sheet-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <aside className="mk-sheet" role="dialog" aria-label="Publish">
        <header>
          <div><h2>Publish</h2><p><Icon name="entire" size={12} />Goes to a public Entire repo, secrets removed</p></div>
          <button className="mk-icon-button" onClick={onClose} aria-label="Close"><Icon name="close" size={14} /></button>
        </header>
        {!signedIn && <div className="mk-notice inset">Run <code>entire login</code> first.</div>}
        <label className="mk-opt"><input type="checkbox" checked={summaries} onChange={(e) => setSummaries(e.target.checked)} />Add AI summaries to checkpoints</label>
        <div className="mk-sheet-list">
          {!publishable.length && <p className="mk-muted">Build and playtest a mod first.</p>}
          {publishable.map((m) => <PublishRow key={m.id} mod={m} published={listings.find((l) => l.slug === m.marketSlug)} disabled={!signedIn} summaries={summaries} onPublished={onPublished} />)}
        </div>
      </aside>
    </div>
  );
}

function PublishRow({ mod, published, disabled, summaries, onPublished }) {
  const [busy, setBusy] = React.useState(false);
  const [result, setResult] = React.useState(null);
  const [started, setStarted] = React.useState(0);
  const [, tick] = React.useState(0);
  React.useEffect(() => { if (!busy) return undefined; const t = setInterval(() => tick((n) => n + 1), 1000); return () => clearInterval(t); }, [busy]);
  const run = (metadataOnly) => {
    setBusy(true);
    setStarted(Date.now());
    setResult(null);
    call("market:publish", { id: mod.id, metadataOnly, withSummaries: summaries })
      .then((r) => { setResult(r); onPublished(); })
      .catch((e) => setResult({ ok: false, error: e.message }))
      .finally(() => setBusy(false));
  };
  const blocked = result && result.ok === false && result.blocked;
  const findings = blocked ? [...(result.gate?.findings || []), ...(result.gate?.suspicious || [])] : [];
  const last = published?.versions?.[0];
  const note = busy ? `Publishing… ${fmtDuration(Date.now() - started) || ""}`
    : result?.ok && !result.skipped ? `Published v${result.version.number}`
    : result?.ok ? "Already published"
    : last ? `v${last.number} published ${since(last.created_at)}` : mod.origin ? `Remix of ${mod.origin.name || mod.origin.marketplace}` : "";
  return (
    <div className="mk-pub">
      <div className="mk-pub-head">
        <span className="mk-avatar small" aria-hidden="true">{mod.name.slice(0, 1)}</span>
        <div><strong>{mod.name}</strong>{note && <small className={result?.ok && !result.skipped ? "ok" : ""}>{note}</small>}</div>
        <button className="mk-button" disabled={busy || disabled} onClick={() => run(false)}>{busy ? "…" : published ? "Update" : "Publish"}</button>
      </div>
      {result && !result.ok && !blocked && <p className="mk-err">{result.error}</p>}
      {blocked && (
        <div className="mk-blocked" role="alert">
          <p>Blocked: {findings.length} possible secret{findings.length === 1 ? "" : "s"} in {[...new Set(findings.map((f) => f.file || "transcript"))].slice(0, 3).join(", ")}.</p>
          {result.metadataOnlyPossible && <button className="mk-button" disabled={busy} onClick={() => run(true)}>Publish without transcripts</button>}
        </div>
      )}
    </div>
  );
}

.studio .view.market-page {
  --mk: var(--accent);
  --mk-soft: rgba(232, 196, 90, 0.1);
  --mk-line: rgba(232, 196, 90, 0.28);
  --en: var(--entire);
  --en-soft: rgba(167, 139, 250, 0.1);
  --en-line: rgba(167, 139, 250, 0.3);
  --en-text: #c4b5fd;
  --mk-sunk: #0d0d0f;
  display: block;
  padding: 30px 32px 42px;
  overflow-y: auto;
}
.studio .market-page *, .studio .market-page *::before, .studio .market-page *::after { box-sizing: border-box; }
.studio .market-page .mk-icon { flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.studio .market-page button, .studio .market-page input, .studio .market-page select { font: inherit; }
.studio .market-page button { cursor: pointer; }
.studio .market-page button:disabled { cursor: not-allowed; opacity: .45; }
.studio .market-page :is(button, input, select):focus-visible { outline: 2px solid var(--mk); outline-offset: 2px; }
.studio .market-page .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.studio .market-page code { font-family: var(--mono); font-size: .92em; }
.studio .market-page .mk-muted { color: var(--text-3); font-size: 12px; }
.studio .market-page .mk-err { margin-top: 8px; color: var(--bad-text); font-size: 12px; overflow-wrap: anywhere; }

/* Header */
.studio .market-page .mk-header { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 22px; }
.studio .market-page .mk-heading { display: flex; align-items: center; gap: 14px; }
.studio .market-page .mk-heading h1 { font-size: 22px; font-weight: 620; letter-spacing: -.025em; }
.studio .market-page .mk-powered { display: inline-flex; align-items: center; gap: 7px; height: 26px; padding: 0 10px; border: 1px solid var(--line); border-radius: 999px; color: var(--text-3); font-size: 11.5px; }
.studio .market-page .mk-powered.on { border-color: var(--en-line); background: var(--en-soft); color: var(--en-text); }
.studio .market-page .mk-powered.off { color: var(--text-2); }
.studio .market-page .mk-powered b { color: var(--warn); font-weight: 500; }
.studio .market-page .mk-notice { margin: 0 0 16px; padding: 9px 12px; border: 1px solid rgba(229,72,77,.28); border-radius: 8px; background: var(--bad-soft); color: var(--bad-text); font-size: 12px; overflow-wrap: anywhere; }
.studio .market-page .mk-notice.inset { margin: 0 22px 12px; }
