.studio .market-page .mk-pubrow span { color: var(--mk-text-3); font-size: 12.5px; }

@media (max-width: 1000px) {
  .studio .market-page .mk-row { grid-template-columns: minmax(0,1fr) 72px; }
  .studio .market-page .mk-row-meta { display: none; }
  .studio .market-page .mk-columns { grid-template-columns: 1fr; gap: 0; }
}

